const data = $input.first().json;

// Extract values
const totalExpense = data.totalMonth || 0;
const categories = data.categories || {};
const highestCategory = data.highestCategory || "";
const highestAmount = data.highestAmount || 0;
const highestRatio = data.ratio || 0;

// Prepare chart arrays
const categoryLabels = Object.keys(categories);
const categoryValues = Object.values(categories);

const html = `
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
<style>
body { font-family: Arial; background:#f4f6f9; padding:20px; }
.container { background:white; padding:20px; border-radius:10px; max-width:800px; margin:auto; }
h1 { text-align:center; }
.summary { background:#667eea; color:white; padding:15px; border-radius:8px; text-align:center; margin-bottom:20px; }
canvas { max-width:100%; margin-top:20px; }
table { width:100%; border-collapse:collapse; margin-top:20px; }
th,td { border:1px solid #ddd; padding:8px; }
th { background:#667eea; color:white; }
</style>
</head>
<body>

<div class="container">

<h1>Monthly Expense Report</h1>

<div class="summary">
<h2>₹${totalExpense.toLocaleString()}</h2>
<p>Total Monthly Expense</p>
</div>

<canvas id="pieChart"></canvas>
<canvas id="barChart"></canvas>

<h3>Category Breakdown</h3>
<table>
<tr>
<th>Category</th>
<th>Amount</th>
<th>%</th>
</tr>

${categoryLabels.map((cat, i) => {
  const percent = totalExpense
    ? ((categoryValues[i] / totalExpense) * 100).toFixed(1)
    : 0;

  return `
  <tr>
    <td>${cat}</td>
    <td>₹${categoryValues[i]}</td>
    <td>${percent}%</td>
  </tr>
  `;
}).join("")}

</table>

<br/>

<strong>Highest Category:</strong>
${highestCategory} — ₹${highestAmount} (${highestRatio}%)

</div>

<script>

const labels = ${JSON.stringify(categoryLabels)};
const dataValues = ${JSON.stringify(categoryValues)};

new Chart(document.getElementById('pieChart'), {
  type: 'pie',
  data: {
    labels: labels,
    datasets: [{
      data: dataValues,
      backgroundColor: [
        '#FF6384','#36A2EB','#FFCE56',
        '#4BC0C0','#9966FF','#FF9F40'
      ]
    }]
  }
});

new Chart(document.getElementById('barChart'), {
  type: 'bar',
  data: {
    labels: labels,
    datasets: [{
      label: 'Amount',
      data: dataValues,
      backgroundColor: '#667eea'
    }]
  },
  options: {
    scales: {
      y: { beginAtZero: true }
    }
  }
});

</script>

</body>
</html>
`;

return [{
  json: {
    html,
    totalExpense,
    categories,
    highestCategory,
    highestAmount,
    highestRatio
  }
}];

const items = $input.all().map(i => i.json);

// =============================
// Aggregations
// =============================
let total = 0;
let categoryTotals = {};
let dailyTotals = {};

for (const row of items) {
  const amount = Number(row.Amount);
  total += amount;

  categoryTotals[row.Category] =
    (categoryTotals[row.Category] || 0) + amount;

  dailyTotals[row.Date] =
    (dailyTotals[row.Date] || 0) + amount;
}

// =============================
// Calculations
// =============================
const avgDaily =
  total / Object.keys(dailyTotals).length;

let highestDay = { date: "", amount: 0 };

for (const date in dailyTotals) {
  if (dailyTotals[date] > highestDay.amount) {
    highestDay = {
      date,
      amount: dailyTotals[date]
    };
  }
}

// Sort categories descending
const sortedCategories = Object.entries(categoryTotals)
  .sort((a, b) => b[1] - a[1]);

// =============================
// Email-Safe HTML Bars
// =============================
const maxValue = Math.max(...Object.values(categoryTotals));

let barSection = "";

for (const [cat, value] of sortedCategories) {
  const percent = (value / maxValue) * 100;

  barSection += `
  <tr>
    <td style="padding:6px 0;">${cat}</td>
    <td style="width:70%;">
      <div style="background:#eee;height:16px;border-radius:4px;">
        <div style="
          background:#4CAF50;
          width:${percent}%;
          height:16px;
          border-radius:4px;">
        </div>
      </div>
    </td>
    <td style="padding-left:10px;">₹ ${value}</td>
  </tr>
  `;
}

// =============================
// QuickChart Graph
// =============================
const chartConfig = {
  type: "bar",
  data: {
    labels: sortedCategories.map(c => c[0]),
    datasets: [{
      label: "Category Spend",
      data: sortedCategories.map(c => c[1])
    }]
  }
};

const chartUrl =
  "https://quickchart.io/chart?width=500&height=300&c=" +
  encodeURIComponent(JSON.stringify(chartConfig));

// =============================
// Full Email HTML
// =============================
const html = `
<h2 style="font-family:Arial;">Monthly Expense Report</h2>

<p><strong>Total Spend:</strong> ₹ ${total}</p>
<p><strong>Average Daily Spend:</strong> ₹ ${avgDaily.toFixed(2)}</p>
<p><strong>Highest Spending Day:</strong> ${highestDay.date} (₹ ${highestDay.amount})</p>

<h3>Category Distribution</h3>

<table style="width:100%;border-collapse:collapse;font-family:Arial;">
  ${barSection}
</table>

<h3 style="margin-top:20px;">Graphical Overview</h3>
<img src="${chartUrl}" alt="Expense Chart" />

<br><br>
<p style="font-size:12px;color:#888;">
Auto-generated report from n8n
</p>
`;

// =============================
// Return JSON
// =============================
return [
  {
    json: {
      total,
      avgDaily,
      highestDay,
      categoryTotals,
      dailyTotals,
      chartUrl,
      html
    }
  }
];
